package wgmodern;
import java.util.*;import net.minecraft.core.BlockPos;import net.minecraft.client.Minecraft;import net.minecraft.world.phys.Vec3;import net.minecraftforge.eventbus.api.SubscribeEvent;import net.minecraftforge.event.TickEvent;import net.minecraftforge.fml.common.Mod;import net.minecraftforge.api.distmarker.Dist;
@Mod.EventBusSubscriber(modid="witchinggadgets",value=Dist.CLIENT)
public class GemEffects {
 private static final Map<BlockPos,Integer> ORES=new LinkedHashMap<>();private static net.minecraft.client.multiplayer.ClientLevel world;private static int highlight;
 public static Vec3 hand(){var p=Minecraft.getInstance().player;boolean third=!Minecraft.getInstance().options.getCameraType().isFirstPerson();double yaw=Math.toRadians((third?p.yBodyRot:p.getYRot())-25-(third?30:0));return p.getEyePosition().add(-Math.cos(yaw)*.5,third?-.75:-.5,-Math.sin(yaw)*.5);}
 public static void receive(WGNetwork.GemEffect effect){var mc=Minecraft.getInstance();if(mc.level==null||mc.player==null)return;if(world!=mc.level){world=mc.level;ORES.clear();highlight=0;}if(effect.kind()==0)ORES.put(effect.pos(),1000);else if(effect.kind()==1)WGEffects.targeted(hand(),Vec3.atCenterOf(effect.pos()),effect.color(),.5f);else if(effect.kind()==2)GuidingThreadRenderer.update("gem_charge",mc.level.getBlockEntity(effect.pos()) instanceof tc4revival.content.VisRelayBlockEntity relay?relay.beamPoint():Vec3.atCenterOf(effect.pos()),hand(),effect.color(),false);}
 @SubscribeEvent public static void tooltip(net.minecraftforge.event.entity.player.ItemTooltipEvent e){if(e.getEntity()==null||!net.minecraft.client.gui.screens.Screen.hasShiftDown()||!tc4revival.client.ClientKnowledge.snapshot().map(k->k.researchMarkers().contains("witchinggadgets:GEMCUTTING")).orElse(false))return;var d=GemAffinities.find(e.getItemStack(),e.getEntity().level());if(d==null)return;if(!d.affinities().isEmpty()){e.getToolTip().add(net.minecraft.network.chat.Component.translatable("wg.desc.gemaffinity").withStyle(net.minecraft.ChatFormatting.DARK_GREEN));for(var tag:d.affinities())e.getToolTip().add(net.minecraft.network.chat.Component.literal(" "+thaumcraft.api.aspects.Aspect.getAspect(tag).getName()).withStyle(net.minecraft.ChatFormatting.DARK_GREEN));}if(!d.aversions().isEmpty()){e.getToolTip().add(net.minecraft.network.chat.Component.translatable("wg.desc.gemaversion").withStyle(net.minecraft.ChatFormatting.RED));for(var tag:d.aversions())e.getToolTip().add(net.minecraft.network.chat.Component.literal(" "+thaumcraft.api.aspects.Aspect.getAspect(tag).getName()).withStyle(net.minecraft.ChatFormatting.RED));}}
 @SubscribeEvent public static void tick(TickEvent.ClientTickEvent e){if(e.phase!=TickEvent.Phase.END)return;var mc=Minecraft.getInstance();if(world!=mc.level){world=mc.level;ORES.clear();highlight=0;}if(world==null||mc.isPaused())return;ORES.replaceAll((p,t)->t-1);ORES.values().removeIf(t->t<=0);}
 @SubscribeEvent public static void render(TickEvent.RenderTickEvent e){var mc=Minecraft.getInstance();if(e.phase!=TickEvent.Phase.START||world!=mc.level||world==null||mc.player==null||ORES.isEmpty()||world.getGameTime()%30!=0)return;var points=new ArrayList<>(ORES.keySet());var pos=points.get(Math.floorMod(highlight++,points.size()));int color=0x330033|(int)((.7f+world.random.nextFloat()*.3f)*255)<<8;WGEffects.targeted(hand(),new Vec3(pos.getX()+.5,pos.getY()+.75,pos.getZ()+.5),color,.05f);}
}
